// Builds hooks/vendor/mermaid-ascii.js: the terminal renderer of beautiful-mermaid
// (MIT, lukilabs), bundled into one ESM file the mod imports. Run after bumping the
// version in package.json: `npm install && npm run build` in this folder.
//
// Two changes to the source, both at build time: the chart plot size becomes settable
// so charts fit the terminal, and the series colour list is exported so the mod can
// tell series apart in the rendered output.

import { build } from 'esbuild'
import { readFile, writeFile, mkdir } from 'node:fs/promises'
import { dirname, join, relative, sep } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const pkgRoot = join(here, 'node_modules', 'beautiful-mermaid')
const outDir = join(here, '..', '..', 'hooks', 'vendor')
const allowed = new Set(['MIT'])

const PATCHES = [
  ['const PLOT_WIDTH = 60', 'let PLOT_WIDTH = 60'],
  ['const PLOT_HEIGHT = 20', 'let PLOT_HEIGHT = 20'],
]

const APPENDIX = `
export const setChartSize = (width: number, height: number): void => {
  PLOT_WIDTH = width
  PLOT_HEIGHT = height
}
export { getSeriesColors }
`

const patchXyChart = {
  name: 'patch-xychart',
  setup(b) {
    b.onLoad({ filter: /[\\/]src[\\/]ascii[\\/]xychart\.ts$/ }, async args => {
      let source = await readFile(args.path, 'utf8')

      for (const [from, to] of PATCHES) {
        if (!source.includes(from)) {
          throw new Error(`xychart.ts no longer contains "${from}"; update the patch for this version`)
        }
        source = source.replace(from, to)
      }

      return { contents: source + APPENDIX, loader: 'ts' }
    })
  },
}

const entry = [
  "export { renderMermaidAscii } from './src/ascii/index.ts'",
  "export { setChartSize, getSeriesColors as seriesColors } from './src/ascii/xychart.ts'",
].join('\n')

const result = await build({
  stdin: { contents: entry, resolveDir: pkgRoot, loader: 'ts', sourcefile: 'entry.ts' },
  bundle: true,
  format: 'esm',
  platform: 'neutral',
  target: 'es2023',
  minify: true,
  legalComments: 'none',
  metafile: true,
  write: false,
  plugins: [patchXyChart],
})

// Every package that ends up in the bundle has to carry a licence we can ship.
const packages = new Set()
for (const input of Object.keys(result.metafile.inputs)) {
  const parts = input.split(/[\\/]/)
  const at = parts.lastIndexOf('node_modules')
  if (at === -1) continue
  const name = parts[at + 1]?.startsWith('@') ? `${parts[at + 1]}/${parts[at + 2]}` : parts[at + 1]
  if (name !== undefined) packages.add(name)
}

const notices = []
for (const name of [...packages].sort()) {
  const pkg = JSON.parse(await readFile(join(here, 'node_modules', name, 'package.json'), 'utf8'))
  if (!allowed.has(pkg.license)) {
    throw new Error(`${name}@${pkg.version} is licensed ${pkg.license}; only ${[...allowed].join(', ')} may be bundled`)
  }
  notices.push(`${name}@${pkg.version} (${pkg.license})`)
}

const licence = (await readFile(join(pkgRoot, 'LICENSE'), 'utf8')).trim()
const header = [
  '// Generated by scripts/vendor/build.mjs. Do not edit.',
  `// Bundles: ${notices.join(', ')}`,
  ...licence.split(/\r?\n/).map(line => `// ${line}`.trimEnd()),
  '',
].join('\n')

await mkdir(outDir, { recursive: true })
const out = join(outDir, 'mermaid-ascii.js')
await writeFile(out, header + result.outputFiles[0].text)

console.log(`wrote ${relative(process.cwd(), out).split(sep).join('/')} (${notices.join(', ')})`)
